    static List<FieldGuide.Entry> entries(){return List.of(
        new FieldGuide.Entry("welcome",FieldGuide.Category.START,FieldGuide.Group.ALL,"Start your first excavation","examplemod:ancient_field_guide",List.of("Ancient Discoveries follows the remains of an accomplished civilization of crafters and smiths. Recover buried artifacts, carefully uncover useful parts, reconstruct equipment and shape its modifiers.","Start with a Sniffer. Expose ancient debris on a walkable surface for it to investigate. Its finds lead to artifacts and, occasionally, a Cruncher egg.","Use the Archaeology Table to excavate finds, then the Reconstruction Table to assemble components. Your excavation quality affects every modifier that the component contributes.","Choose a category or search from any page. Articles have named sections: read the overview first, then open details when you need them. Back returns to your previous search or article.","This book contains general knowledge. Your item tooltips show the values actually rolled on your own components and tools. Unread ancient runes stay hidden until you unveil them."),List.of("sniffers","archaeology_table","reconstruction","modifier_basics"),"getting started tutorial progression book journal help",List.of(new FieldGuide.Section("The idea",List.of("Ancient Discoveries follows the remains of an accomplished civilization of crafters and smiths. Recover buried artifacts, carefully uncover useful parts, reconstruct equipment and shape its modifiers.")),new FieldGuide.Section("1. Find an artifact",List.of("Start with a Sniffer. Expose ancient debris on a walkable surface for it to investigate. Its finds lead to artifacts and, occasionally, a Cruncher egg.")),new FieldGuide.Section("2. Uncover and rebuild",List.of("Use the Archaeology Table to excavate finds, then the Reconstruction Table to assemble components. Your excavation quality affects every modifier that the component contributes.")),new FieldGuide.Section("Using the book",List.of("Choose a category or search from any page. Articles have named sections: read the overview first, then open details when you need them. Back returns to your previous search or article.")),new FieldGuide.Section("Your own equipment",List.of("This book contains general knowledge. Your item tooltips show the values actually rolled on your own components and tools. Unread ancient runes stay hidden until you unveil them.")))),
        new FieldGuide.Entry("book_controls",FieldGuide.Category.START,FieldGuide.Group.ALL,"Using this field guide","examplemod:ancient_field_guide",List.of("Craft a book with one paper for the Field Journal. Workshop Manual and Trail Guide are comparison editions in the creative tab; all editions contain the same information.","Home opens this edition's contents. Categories cover creatures, artifacts, excavation, equipment and customization stations. Modifiers opens a topic index.","Search looks through the whole guide, including descriptions and modifier IDs. All words must match. Clear empties search. Arrows and the mouse wheel turn pages. Select a named section to read details. Related opens connected articles; Back restores your previous view.","Escape or the close button closes the book. Reading never consumes the book, changes equipment or rolls an artifact. The last page and search are remembered during the current play session.","Hover a reconstructed tool and hold Shift while scrolling to browse its modifier pages. Effective values and grades remain on the tool; definitions and rules live here.","Craft ancient field guide: book + paper, in any arrangement."),List.of("welcome","modifier_basics"),"controls search keyboard navigation pages",List.of(new FieldGuide.Section("Get a book",List.of("Craft a book with one paper for the Field Journal. Workshop Manual and Trail Guide are comparison editions in the creative tab; all editions contain the same information.")),new FieldGuide.Section("Browse",List.of("Home opens this edition's contents. Categories cover creatures, artifacts, excavation, equipment and customization stations. Modifiers opens a topic index.")),new FieldGuide.Section("Search and navigate",List.of("Search looks through the whole guide, including descriptions and modifier IDs. All words must match. Clear empties search. Arrows and the mouse wheel turn pages. Select a named section to read details. Related opens connected articles; Back restores your previous view.")),new FieldGuide.Section("Close and return",List.of("Escape or the close button closes the book. Reading never consumes the book, changes equipment or rolls an artifact. The last page and search are remembered during the current play session.")),new FieldGuide.Section("Inspect your tool",List.of("Hover a reconstructed tool and hold Shift while scrolling to browse its modifier pages. Effective values and grades remain on the tool; definitions and rules live here.")),new FieldGuide.Section("Recipe",List.of("Craft ancient field guide: book + paper, in any arrangement.")))),
        new FieldGuide.Entry("sniffers",FieldGuide.Category.CREATURES,FieldGuide.Group.ALL,"Sniffers and ancient debris","minecraft:sniffer_egg",List.of("Brush suspicious sand in warm ocean ruins to find a vanilla Sniffer egg. Hatch it and raise the Sniffer. Adults can investigate exposed ancient debris on a walkable surface; buried debris is not a target. Adults breed with torchflower seeds.","When the Sniffer successfully digs at exposed ancient debris, that debris breaks and yields netherite scrap and an artifact. Mob griefing must allow the interaction.","There is also a one-in-fifteen chance of a Cruncher egg from this excavation. Ordinary Sniffer digging still has its normal uses.","Adult sniffers drop a Sniffer Head when killed. The head is a decorative trophy, with wall attachment and sixteen floor rotations."),List.of("crunchers","artifacts","sniffer_head"),"sniff ancient debris netherite scrap cruncher egg",List.of(new FieldGuide.Section("Raise a Sniffer",List.of("Brush suspicious sand in warm ocean ruins to find a vanilla Sniffer egg. Hatch it and raise the Sniffer. Adults can investigate exposed ancient debris on a walkable surface; buried debris is not a target. Adults breed with torchflower seeds.")),new FieldGuide.Section("Expose ancient debris",List.of("When the Sniffer successfully digs at exposed ancient debris, that debris breaks and yields netherite scrap and an artifact. Mob griefing must allow the interaction.")),new FieldGuide.Section("What it finds",List.of("There is also a one-in-fifteen chance of a Cruncher egg from this excavation. Ordinary Sniffer digging still has its normal uses.")),new FieldGuide.Section("Decorative head",List.of("Adult sniffers drop a Sniffer Head when killed. The head is a decorative trophy, with wall attachment and sixteen floor rotations.")))),
        new FieldGuide.Entry("sniffer_head",FieldGuide.Category.CREATURES,FieldGuide.Group.ALL,"The Sniffer Head","examplemod:example_block",List.of("The Sniffer Head is a decorative drop from a killed Sniffer. It is also in the creative menu.","Place it on a wall to face directly out from the supporting surface. Floor placement supports sixteen rotations, including diagonals. The back sits flush against its support."),List.of("sniffers"),"skull head trophy wall rotation",List.of(new FieldGuide.Section("Overview",List.of("The Sniffer Head is a decorative drop from a killed Sniffer. It is also in the creative menu.")),new FieldGuide.Section("Details 2",List.of("Place it on a wall to face directly out from the supporting surface. Floor placement supports sixteen rotations, including diagonals. The back sits flush against its support.")))),
        new FieldGuide.Entry("crunchers",FieldGuide.Category.CREATURES,FieldGuide.Group.ALL,"Crunchers","examplemod:cruncher_spawn_egg",List.of("The Cruncher is a Nether relative of the Sniffer, with heavy jaws suited to breaking ancient geodes. Hatch its egg to raise one, or use the creative spawn egg for testing.","Crunchers approach geodes from beside the block and crunch them with their jaws. The geode is consumed and produces an artifact; it is not a block the player must stand the Cruncher on.","Crunchers eat wither roses. Their visual design uses obsidian, Nether colors and animated magma veins.","An infected Cruncher has its own sculk transformation and attached parasite appearance. Further specialized infected behavior is planned."),List.of("cruncher_egg","ancient_geodes","sculk_parasites"),"nether mob jaws wither rose food breeding",List.of(new FieldGuide.Section("Meet the Cruncher",List.of("The Cruncher is a Nether relative of the Sniffer, with heavy jaws suited to breaking ancient geodes. Hatch its egg to raise one, or use the creative spawn egg for testing.")),new FieldGuide.Section("Crunch a geode",List.of("Crunchers approach geodes from beside the block and crunch them with their jaws. The geode is consumed and produces an artifact; it is not a block the player must stand the Cruncher on.")),new FieldGuide.Section("Care and appearance",List.of("Crunchers eat wither roses. Their visual design uses obsidian, Nether colors and animated magma veins.")),new FieldGuide.Section("Infection",List.of("An infected Cruncher has its own sculk transformation and attached parasite appearance. Further specialized infected behavior is planned.")))),
        new FieldGuide.Entry("cruncher_egg",FieldGuide.Category.CREATURES,FieldGuide.Group.ALL,"Hatching a Cruncher egg","examplemod:cruncher_egg",List.of("A Cruncher egg can be found when an adult Sniffer excavates exposed ancient debris. Its chance is one in fifteen.","The placed egg progresses through three visible stages. Normal hatching takes about twenty minutes, plus small random stage delays, matching the normal Sniffer egg timing.","Place the egg on warped nylium to reduce the base hatching time to about ten minutes. It does not use the Sniffer egg moss boost.","The final hatch needs clear space for the baby. If the baby would collide, the egg waits and retries instead of losing the hatchling."),List.of("sniffers","crunchers"),"hatch incubation warped nylium magma lava stages",List.of(new FieldGuide.Section("Overview",List.of("A Cruncher egg can be found when an adult Sniffer excavates exposed ancient debris. Its chance is one in fifteen.")),new FieldGuide.Section("Details 2",List.of("The placed egg progresses through three visible stages. Normal hatching takes about twenty minutes, plus small random stage delays, matching the normal Sniffer egg timing.")),new FieldGuide.Section("Details 3",List.of("Place the egg on warped nylium to reduce the base hatching time to about ten minutes. It does not use the Sniffer egg moss boost.")),new FieldGuide.Section("Details 4",List.of("The final hatch needs clear space for the baby. If the baby would collide, the egg waits and retries instead of losing the hatchling.")))),
        new FieldGuide.Entry("ancient_geodes",FieldGuide.Category.ARTIFACTS,FieldGuide.Group.ALL,"Ancient geodes","examplemod:ancient_geode",List.of("Ancient geodes are obsidian-like relics found as an additional reward from Ominous Vaults. The current extra-geode chance is twenty percent.","Place one where a Cruncher can walk up to it. The Cruncher crunches the geode and releases an artifact suitable for the Archaeology Table.","Geodes and Sniffer debris finds are different artifact sources. Neither source currently supplies Legendary or Unique artifacts; acquisition for those rarities is reserved for later progression."),List.of("crunchers","artifacts"),"ominous vault trial chamber geode obsidian rare",List.of(new FieldGuide.Section("Overview",List.of("Ancient geodes are obsidian-like relics found as an additional reward from Ominous Vaults. The current extra-geode chance is twenty percent.")),new FieldGuide.Section("Details 2",List.of("Place one where a Cruncher can walk up to it. The Cruncher crunches the geode and releases an artifact suitable for the Archaeology Table.")),new FieldGuide.Section("Details 3",List.of("Geodes and Sniffer debris finds are different artifact sources. Neither source currently supplies Legendary or Unique artifacts; acquisition for those rarities is reserved for later progression.")))),
        new FieldGuide.Entry("sculk_parasites",FieldGuide.Category.CREATURES,FieldGuide.Group.ALL,"Sculk parasites","examplemod:skulk_parasite_spawn_egg",List.of("Sculk parasites naturally appear in the Deep Dark and Ancient Cities. Natural spawn checks keep their local population sparse. Their movement does not continually trigger sculk vibrations.","A parasite jumps onto a supported mob and merges with it. Players cannot be infected. Infected hostile mobs are more dangerous and reward more experience; normally passive hosts become hostile.","The transformation preserves the host's normal identity and applicable texture variants while adding sculk growth, an attached parasite and animated infection details.","Bosses such as the Ender Dragon are excluded. So are tadpoles, ghasts and happy ghasts, endermites and silverfish, ordinary fish, squid and glow squid, bats, allays and vexes.","Slimes, magma cubes, blazes, breezes and shulkers remain supported. Sniffers and Crunchers use specialized infected visuals."),List.of("sniffers","crunchers"),"skulk sculk parasite infection infected hostile deep dark ancient city sensors cow zombie panda llama iron golem infected animals mobs",List.of(new FieldGuide.Section("Overview",List.of("Sculk parasites naturally appear in the Deep Dark and Ancient Cities. Natural spawn checks keep their local population sparse. Their movement does not continually trigger sculk vibrations.")),new FieldGuide.Section("Details 2",List.of("A parasite jumps onto a supported mob and merges with it. Players cannot be infected. Infected hostile mobs are more dangerous and reward more experience; normally passive hosts become hostile.")),new FieldGuide.Section("Details 3",List.of("The transformation preserves the host's normal identity and applicable texture variants while adding sculk growth, an attached parasite and animated infection details.")),new FieldGuide.Section("Details 4",List.of("Bosses such as the Ender Dragon are excluded. So are tadpoles, ghasts and happy ghasts, endermites and silverfish, ordinary fish, squid and glow squid, bats, allays and vexes.")),new FieldGuide.Section("Details 5",List.of("Slimes, magma cubes, blazes, breezes and shulkers remain supported. Sniffers and Crunchers use specialized infected visuals.")))),
        new FieldGuide.Entry("artifacts",FieldGuide.Category.ARTIFACTS,FieldGuide.Group.ALL,"Artifacts and rarity","examplemod:ancient_artifact",List.of("Artifacts are sealed specimens containing an ancient find in a rock matrix. A Sniffer or Cruncher can recover them. The Archaeology Table reveals the find through a cleaning minigame.","The six artifact rarities are Common, Uncommon, Rare, Epic, Legendary and Unique. Rarity affects available modifiers, the odds of stronger value tiers, modifier-count attempts and scaling grades.","A higher rarity offers better opportunities, not a guaranteed perfect component. Every modifier family has its own tier bands and rarity weights. Each modifier entry lists those weights.","Current Sniffer finds: seventy percent Common, twenty-five percent Uncommon and five percent Rare. Cruncher geode finds: eighty percent Rare and twenty percent Epic.","Legendary and Unique acquisition is reserved for later progression. They are available in creative mode. This guide does not add drop chances for them."),List.of("rock_matrices","modifier_basics","scaling_and_quality"),"rarity common uncommon rare epic legendary unique drop chances",List.of(new FieldGuide.Section("Overview",List.of("Artifacts are sealed specimens containing an ancient find in a rock matrix. A Sniffer or Cruncher can recover them. The Archaeology Table reveals the find through a cleaning minigame.")),new FieldGuide.Section("Details 2",List.of("The six artifact rarities are Common, Uncommon, Rare, Epic, Legendary and Unique. Rarity affects available modifiers, the odds of stronger value tiers, modifier-count attempts and scaling grades.")),new FieldGuide.Section("Details 3",List.of("A higher rarity offers better opportunities, not a guaranteed perfect component. Every modifier family has its own tier bands and rarity weights. Each modifier entry lists those weights.")),new FieldGuide.Section("Details 4",List.of("Current Sniffer finds: seventy percent Common, twenty-five percent Uncommon and five percent Rare. Cruncher geode finds: eighty percent Rare and twenty percent Epic.")),new FieldGuide.Section("Details 5",List.of("Legendary and Unique acquisition is reserved for later progression. They are available in creative mode. This guide does not add drop chances for them.")))),
        new FieldGuide.Entry("rock_matrices",FieldGuide.Category.ARTIFACTS,FieldGuide.Group.ALL,"Rock matrices and hidden finds","examplemod:ancient_artifact",List.of("Artifacts may be encased in sandstone, shale, deepslate, basalt or obsidian. Harder matrices need more clearing and put more emphasis on the right tool for each layer.","Rarer specimens favor tougher matrices. The rock is a shell around the find; its material is not the same thing as a Nether or End influence.","Potential recovered finds include pickaxe head pieces, a connector, a handle, other equipment heads and blades, resonant cores and salvage materials.","Once a specimen is sealed, its study is stable. Completing an excavation and claiming the reward does not let you repeatedly reroll the same find."),List.of("archaeology_table","excavation_tools","influences"),"sandstone shale deepslate basalt obsidian stone matrix rocks",List.of(new FieldGuide.Section("Overview",List.of("Artifacts may be encased in sandstone, shale, deepslate, basalt or obsidian. Harder matrices need more clearing and put more emphasis on the right tool for each layer.")),new FieldGuide.Section("Details 2",List.of("Rarer specimens favor tougher matrices. The rock is a shell around the find; its material is not the same thing as a Nether or End influence.")),new FieldGuide.Section("Details 3",List.of("Potential recovered finds include pickaxe head pieces, a connector, a handle, other equipment heads and blades, resonant cores and salvage materials.")),new FieldGuide.Section("Details 4",List.of("Once a specimen is sealed, its study is stable. Completing an excavation and claiming the reward does not let you repeatedly reroll the same find.")))),
        new FieldGuide.Entry("archaeology_table",FieldGuide.Category.EXCAVATION,FieldGuide.Group.ALL,"The Archaeology Table","examplemod:archaeology_table",List.of("This two-block workbench holds an artifact and four field tools: drill, brush, hammer and magnifying lens. Items stored in it appear physically on the tabletop.","Put an artifact in the artifact slot. Switch to the excavation workspace for a large view of the encased find. The inventory view is still available for moving tools and rewards.","Pick up a tool from the field kit and click or drag over the specimen. Clicking another tool returns the held tool to its proper position and switches to the new one.","Clear the covering rock while preserving the inclusion. Thick crust calls for the hammer or drill; loose material near the find is safer to brush. The lens helps identify hidden material.","When the table says Ready to recover, use Recover with the output slot empty. Take the recovered component before starting another reward. Table contents persist when the screen is closed.","Craft archaeology table: grid rows PPP / SIS / S.S. A dot means an empty cell. P = any planks; S = stick; I = iron ingot."),List.of("excavation_tools","tool_tiers","scaling_and_quality"),"archeology archaeology excavation minigame recover extract artifact inventory field kit",List.of(new FieldGuide.Section("The workbench",List.of("This two-block workbench holds an artifact and four field tools: drill, brush, hammer and magnifying lens. Items stored in it appear physically on the tabletop.")),new FieldGuide.Section("Load a specimen",List.of("Put an artifact in the artifact slot. Switch to the excavation workspace for a large view of the encased find. The inventory view is still available for moving tools and rewards.")),new FieldGuide.Section("Choose a tool",List.of("Pick up a tool from the field kit and click or drag over the specimen. Clicking another tool returns the held tool to its proper position and switches to the new one.")),new FieldGuide.Section("Clear the rock",List.of("Clear the covering rock while preserving the inclusion. Thick crust calls for the hammer or drill; loose material near the find is safer to brush. The lens helps identify hidden material.")),new FieldGuide.Section("Recover your find",List.of("When the table says Ready to recover, use Recover with the output slot empty. Take the recovered component before starting another reward. Table contents persist when the screen is closed.")),new FieldGuide.Section("Recipe",List.of("Craft archaeology table: grid rows PPP / SIS / S.S. A dot means an empty cell. P = any planks; S = stick; I = iron ingot.")))),
        new FieldGuide.Entry("excavation_tools",FieldGuide.Category.EXCAVATION,FieldGuide.Group.ALL,"Choosing excavation tools","examplemod:archaeology_drill",List.of("Drill: precise removal for working through cover. Use care near delicate material.","Brush: gentle cleaning of loose sediment, suited to exposed edges and the final pass.","Hammer: broad removal of thick crust. Efficient for hard cover and risky near the inclusion.","Magnifying lens: inspection that helps reveal where material lies beneath the surface without removing that cover.","Tool choice, covering thickness and how close you are to the find matter more than simply repeating the same action everywhere. Damage reduces the recovered quality.","An ordinary Minecraft brush is the basic brush. The custom drill, hammer and lens recipes are listed on the following pages.","Craft archaeology drill: grid rows .IR / .SI / .S.. A dot means an empty cell. I = iron ingot; R = redstone; S = stick.","Craft archaeology hammer: grid rows II. / .S. / .S.. A dot means an empty cell. I = iron ingot; S = stick.","Craft magnifying glass: grid rows GI / .S. A dot means an empty cell. G = glass pane; I = iron ingot; S = stick."),List.of("archaeology_table","tool_tiers","scaling_and_quality"),"drill brush hammer lens magnifying glass tools damage condition",List.of(new FieldGuide.Section("Overview",List.of("Drill: precise removal for working through cover. Use care near delicate material.")),new FieldGuide.Section("Details 2",List.of("Brush: gentle cleaning of loose sediment, suited to exposed edges and the final pass.")),new FieldGuide.Section("Details 3",List.of("Hammer: broad removal of thick crust. Efficient for hard cover and risky near the inclusion.")),new FieldGuide.Section("Details 4",List.of("Magnifying lens: inspection that helps reveal where material lies beneath the surface without removing that cover.")),new FieldGuide.Section("Details 5",List.of("Tool choice, covering thickness and how close you are to the find matter more than simply repeating the same action everywhere. Damage reduces the recovered quality.")),new FieldGuide.Section("Details 6",List.of("An ordinary Minecraft brush is the basic brush. The custom drill, hammer and lens recipes are listed on the following pages.")),new FieldGuide.Section("Recipe",List.of("Craft archaeology drill: grid rows .IR / .SI / .S.. A dot means an empty cell. I = iron ingot; R = redstone; S = stick.","Craft archaeology hammer: grid rows II. / .S. / .S.. A dot means an empty cell. I = iron ingot; S = stick.","Craft magnifying glass: grid rows GI / .S. A dot means an empty cell. G = glass pane; I = iron ingot; S = stick.")))),
        new FieldGuide.Entry("tool_tiers",FieldGuide.Category.EXCAVATION,FieldGuide.Group.ALL,"Field-tool upgrades","examplemod:precision_drill",List.of("Field tools have basic, precision and resonant versions. Upgrades improve excavation control, speed, tool durability and inspection behavior.","Precision upgrades use recovered components or fragments and diamonds. Resonant upgrades use resonant cores and netherite scrap. Use the smithing upgrades appropriate to the tool.","Upgrading preserves the tool's custom name, damage and enchantments. The drill, brush, hammer and lens retain their distinct jobs at every tier."),List.of("excavation_tools","archaeology_table"),"precision resonant field tool smithing upgrade diamond netherite scrap",List.of(new FieldGuide.Section("Overview",List.of("Field tools have basic, precision and resonant versions. Upgrades improve excavation control, speed, tool durability and inspection behavior.")),new FieldGuide.Section("Details 2",List.of("Precision upgrades use recovered components or fragments and diamonds. Resonant upgrades use resonant cores and netherite scrap. Use the smithing upgrades appropriate to the tool.")),new FieldGuide.Section("Details 3",List.of("Upgrading preserves the tool's custom name, damage and enchantments. The drill, brush, hammer and lens retain their distinct jobs at every tier.")))),
        new FieldGuide.Entry("scaling_and_quality",FieldGuide.Category.EQUIPMENT,FieldGuide.Group.ALL,"Quality and scaling grades","examplemod:pickaxe_left_tip",List.of("A recovered component remembers its excavation score. That score multiplies each numeric modifier on that component: a +10% mining-speed roll at 50% quality contributes +5%.","Original excavation provenance stays recorded. Component restoration can improve current quality up to 120%. At zero quality, a component grants no modifier effect.","F, D, C, B, A and S are scaling grades. They are independent of base value tier and influence. A high base roll and strong grade work well together.","Numeric grade growth per ascension is F +6%, D +10%, C +15%, B +22%, A +32%, S +45%, relative to that modifier's quality-adjusted base. Growth adds; it does not compound.","An ordinary level selects one to three numeric contributions for a small grade-based increase. Per selected level: F 0.05%, D 0.10%, C 0.15%, B 0.25%, A 0.35%, S 0.50% of base.","Milestone perks gain stages instead of meaningless numeric bonuses. Stages unlock at ascensions 4/7/10 for F/D, 3/6/9 for C/B and 2/5/8 for A/S."),List.of("modifier_basics","levels","restoration"),"score quality extraction excavation grade scaling f d c b a s 0 50 100 120 percent",List.of(new FieldGuide.Section("Quality",List.of("A recovered component remembers its excavation score. That score multiplies each numeric modifier on that component: a +10% mining-speed roll at 50% quality contributes +5%.")),new FieldGuide.Section("Scaling grades",List.of("Original excavation provenance stays recorded. Component restoration can improve current quality up to 120%. At zero quality, a component grants no modifier effect.")),new FieldGuide.Section("Numeric growth",List.of("F, D, C, B, A and S are scaling grades. They are independent of base value tier and influence. A high base roll and strong grade work well together.")),new FieldGuide.Section("Milestone perks",List.of("Numeric grade growth per ascension is F +6%, D +10%, C +15%, B +22%, A +32%, S +45%, relative to that modifier's quality-adjusted base. Growth adds; it does not compound.")),new FieldGuide.Section("Details 5",List.of("An ordinary level selects one to three numeric contributions for a small grade-based increase. Per selected level: F 0.05%, D 0.10%, C 0.15%, B 0.25%, A 0.35%, S 0.50% of base.")),new FieldGuide.Section("Details 6",List.of("Milestone perks gain stages instead of meaningless numeric bonuses. Stages unlock at ascensions 4/7/10 for F/D, 3/6/9 for C/B and 2/5/8 for A/S.")))),
        new FieldGuide.Entry("reconstruction",FieldGuide.Category.EQUIPMENT,FieldGuide.Group.ALL,"Reconstructing equipment","examplemod:reconstruction_table",List.of("Use the Reconstruction Table to select an equipment pattern, place its matching recovered pieces and assemble the result. Each selected pattern shows the parts it requires.","A pickaxe uses three top pieces: left tip, head bridge and right tip. Beneath them sit a connector and handle. All five pieces keep their individual scores and modifier records.","Sword, axe, shovel, hoe, mace and spear patterns are also available. Handles and connectors use universal modifiers that work on all reconstructed tool types.","The finished tool keeps each part's quality, saved rolls and customization provenance. Repeated contributions combine up to their relevant caps.","The pickaxe has the developed mining modifier and progression system. Further specialized modifiers for other equipment can be added later.","Craft reconstruction table: grid rows PPP / .C. / S.S. A dot means an empty cell. P = any planks; C = crafting table; S = stick."),List.of("pickaxe_core","modifier_basics","levels"),"reconstruction table crafting pickaxe sword axe shovel hoe mace spear pieces connector handle",List.of(new FieldGuide.Section("Choose a pattern",List.of("Use the Reconstruction Table to select an equipment pattern, place its matching recovered pieces and assemble the result. Each selected pattern shows the parts it requires.")),new FieldGuide.Section("Pickaxe parts",List.of("A pickaxe uses three top pieces: left tip, head bridge and right tip. Beneath them sit a connector and handle. All five pieces keep their individual scores and modifier records.")),new FieldGuide.Section("Other patterns",List.of("Sword, axe, shovel, hoe, mace and spear patterns are also available. Handles and connectors use universal modifiers that work on all reconstructed tool types.")),new FieldGuide.Section("Saved component data",List.of("The finished tool keeps each part's quality, saved rolls and customization provenance. Repeated contributions combine up to their relevant caps.")),new FieldGuide.Section("What is developed",List.of("The pickaxe has the developed mining modifier and progression system. Further specialized modifiers for other equipment can be added later.")),new FieldGuide.Section("Recipe",List.of("Craft reconstruction table: grid rows PPP / .C. / S.S. A dot means an empty cell. P = any planks; C = crafting table; S = stick.")))),
        new FieldGuide.Entry("pickaxe_core",FieldGuide.Category.EQUIPMENT,FieldGuide.Group.ALL,"The reconstructed pickaxe","examplemod:restored_ancient_pickaxe",List.of("A reconstructed pickaxe combines the three mining head pieces with a universal connector and handle. A carefully assembled build can substantially outperform an enchanted vanilla pickaxe.","The innate mining multiplier is 1 plus twice the average quality of its three head pieces. Heads at 50% give 2x native speed; 100% gives 3x; 120% gives 3.4x. This multiplies native Efficiency and Haste too.","The pickaxe has a 200-point resonance store. Primary mining and holding the tool generate quality-scaled core charge. Dedicated generation modifiers support more simultaneous spenders.","Crouch to enable area-mining perks. Native extra breaks consume durability, respect cancellation and share a limit of 64 extra blocks within a loaded 16-block range.","Extra breaks cannot recurse, farm tool XP or generate primary bonuses or resonance. Native Fortune, Silk, furnace handling and pure material conversions still compose with secondary loot.","Recoil uses right-click air for a backward blink. Chorus uses sneak-right-click air for a forward blink. Both require a safe destination."),List.of("levels","ascension","resonance","modifier_basics"),"mining core speed efficiency fortune area crouch pickaxe",List.of(new FieldGuide.Section("Overview",List.of("A reconstructed pickaxe combines the three mining head pieces with a universal connector and handle. A carefully assembled build can substantially outperform an enchanted vanilla pickaxe.")),new FieldGuide.Section("Details 2",List.of("The innate mining multiplier is 1 plus twice the average quality of its three head pieces. Heads at 50% give 2x native speed; 100% gives 3x; 120% gives 3.4x. This multiplies native Efficiency and Haste too.")),new FieldGuide.Section("Details 3",List.of("The pickaxe has a 200-point resonance store. Primary mining and holding the tool generate quality-scaled core charge. Dedicated generation modifiers support more simultaneous spenders.")),new FieldGuide.Section("Details 4",List.of("Crouch to enable area-mining perks. Native extra breaks consume durability, respect cancellation and share a limit of 64 extra blocks within a loaded 16-block range.")),new FieldGuide.Section("Details 5",List.of("Extra breaks cannot recurse, farm tool XP or generate primary bonuses or resonance. Native Fortune, Silk, furnace handling and pure material conversions still compose with secondary loot.")),new FieldGuide.Section("Details 6",List.of("Recoil uses right-click air for a backward blink. Chorus uses sneak-right-click air for a forward blink. Both require a safe destination.")))),
        new FieldGuide.Entry("levels",FieldGuide.Category.EQUIPMENT,FieldGuide.Group.ALL,"Tool levels and mastery","examplemod:restored_ancient_pickaxe",List.of("Valid Survival or Adventure pickaxe mining grants tool XP. Creative mining, canceled breaks, incorrect-tool targets and secondary area breaks do not farm levels.","The pickaxe levels from 1 to 100. Every tenth level is an ascension gate: collect its materials and ascend before gaining more tool XP. XP at an unpaid gate is not banked.","Ordinary levels award small grade-scaled bonuses to one to three numeric contributions. Level-up sound marks a successful gain. Milestone perks advance with ascensions.","At full mastery, the Rally Mining modifier converts its extra tool-XP opportunity into player XP and resonance, so that investment remains useful."),List.of("ascension","scaling_and_quality","pickaxe_core"),"levels experience xp mastery level 100 gates",List.of(new FieldGuide.Section("Overview",List.of("Valid Survival or Adventure pickaxe mining grants tool XP. Creative mining, canceled breaks, incorrect-tool targets and secondary area breaks do not farm levels.")),new FieldGuide.Section("Details 2",List.of("The pickaxe levels from 1 to 100. Every tenth level is an ascension gate: collect its materials and ascend before gaining more tool XP. XP at an unpaid gate is not banked.")),new FieldGuide.Section("Details 3",List.of("Ordinary levels award small grade-scaled bonuses to one to three numeric contributions. Level-up sound marks a successful gain. Milestone perks advance with ascensions.")),new FieldGuide.Section("Details 4",List.of("At full mastery, the Rally Mining modifier converts its extra tool-XP opportunity into player XP and resonance, so that investment remains useful.")))),
        new FieldGuide.Entry("ascension",FieldGuide.Category.STATIONS,FieldGuide.Group.ALL,"The Ascender","examplemod:ascender",List.of("The prototype Ascender has a tool slot and storage for the materials required by that tool's modifiers. Place the pickaxe at a ten-level gate and supply every listed resource.","Each rolled modifier occurrence has a resource binding. Cost increases with the upcoming ascension number. Repeated modifiers and materials combine into the total requirement.","Once every cost is present, the tool ascends and the exact materials are consumed. Ascension raises numeric contributions according to their grades and may unlock perk stages.","This prototype has no crafting recipe. Its final late-game construction is reserved for future progression. It is available in creative mode."),List.of("levels","scaling_and_quality","modifier_basics"),"ascender ascend materials resources level gate",List.of(new FieldGuide.Section("Overview",List.of("The prototype Ascender has a tool slot and storage for the materials required by that tool's modifiers. Place the pickaxe at a ten-level gate and supply every listed resource.")),new FieldGuide.Section("Details 2",List.of("Each rolled modifier occurrence has a resource binding. Cost increases with the upcoming ascension number. Repeated modifiers and materials combine into the total requirement.")),new FieldGuide.Section("Details 3",List.of("Once every cost is present, the tool ascends and the exact materials are consumed. Ascension raises numeric contributions according to their grades and may unlock perk stages.")),new FieldGuide.Section("Details 4",List.of("This prototype has no crafting recipe. Its final late-game construction is reserved for future progression. It is available in creative mode.")))),
        new FieldGuide.Entry("modifier_basics",FieldGuide.Category.EQUIPMENT,FieldGuide.Group.ALL,"Reading modifiers and value tiers","examplemod:pickaxe_head_bridge",List.of("A modifier family is selected by its relative weight. Then rarity weights select one of that modifier's value tiers, followed by a value within that band. Different families may have different numbers of tiers.","T1 is the strongest value tier. Common artifacts favor low bands, with occasional stronger results where allowed. High rarities favor stronger bands and have more chances to add extra modifiers.","Value tier, F-S scaling grade, excavation quality and influence are separate properties. Your tooltips show your actual values; each modifier's book entry explains its operation, limits and tier bands.","Handles and connectors roll the universal pool. Mining head pieces roll mining effects. Some harvest effects exclude each other on one piece, and Silk Touch takes priority over Fortune and furnace loot.","Fortune contributions add above a native Fortune enchantment up to X. Applicable mining-XP bonuses add up to +2000%. Conditional mining-speed bonuses add up to +800%, then multiply the core and general speed bonus.","The Modifiers category contains all 120 definitions. Use its topic filter for speed, loot, area mining, resonance, survival, universal parts or either influence."),List.of("scaling_and_quality","influences","unveiler"),"modifiers affixes rolls tiers tier weights rarity prefixes suffixes",List.of(new FieldGuide.Section("Rolling a modifier",List.of("A modifier family is selected by its relative weight. Then rarity weights select one of that modifier's value tiers, followed by a value within that band. Different families may have different numbers of tiers.")),new FieldGuide.Section("Value tiers",List.of("T1 is the strongest value tier. Common artifacts favor low bands, with occasional stronger results where allowed. High rarities favor stronger bands and have more chances to add extra modifiers.")),new FieldGuide.Section("Four different properties",List.of("Value tier, F-S scaling grade, excavation quality and influence are separate properties. Your tooltips show your actual values; each modifier's book entry explains its operation, limits and tier bands.")),new FieldGuide.Section("Part roles and exclusions",List.of("Handles and connectors roll the universal pool. Mining head pieces roll mining effects. Some harvest effects exclude each other on one piece, and Silk Touch takes priority over Fortune and furnace loot.")),new FieldGuide.Section("Combined limits",List.of("Fortune contributions add above a native Fortune enchantment up to X. Applicable mining-XP bonuses add up to +2000%. Conditional mining-speed bonuses add up to +800%, then multiply the core and general speed bonus.")),new FieldGuide.Section("Look up a modifier",List.of("The Modifiers category contains all 120 definitions. Use its topic filter for speed, loot, area mining, resonance, survival, universal parts or either influence.")))),
        new FieldGuide.Entry("resonance",FieldGuide.Category.EQUIPMENT,FieldGuide.Group.ALL,"Resonance and combinations","examplemod:restored_ancient_pickaxe",List.of("Resonance is energy stored on an assembled pickaxe, with a capacity of 200. The innate core supplies quality-scaled charge on primary breaks and periodically while held.","Battery modifiers add charge from activities such as gem mining, movement, furnace processing or trading some current mining XP. They can support multiple spenders.","Spenders provide effects such as area excavation, Haste, repair, bonus loot, teleportation and protection. Each effect has its own cost, conditions and cooldown.","Consumers share the same store and run in a defined mining-event order. If one spends the remaining energy, another may have to wait. Entanglement can refund part of spending and share that refund with nearby allies.","Secondary breaks and remote collection cannot recursively farm resonance. Read individual modifier entries for stage values and exact conditions."),List.of("pickaxe_core","modifier_basics","ascension"),"resonance battery charge energy combo synergy",List.of(new FieldGuide.Section("Overview",List.of("Resonance is energy stored on an assembled pickaxe, with a capacity of 200. The innate core supplies quality-scaled charge on primary breaks and periodically while held.")),new FieldGuide.Section("Details 2",List.of("Battery modifiers add charge from activities such as gem mining, movement, furnace processing or trading some current mining XP. They can support multiple spenders.")),new FieldGuide.Section("Details 3",List.of("Spenders provide effects such as area excavation, Haste, repair, bonus loot, teleportation and protection. Each effect has its own cost, conditions and cooldown.")),new FieldGuide.Section("Details 4",List.of("Consumers share the same store and run in a defined mining-event order. If one spends the remaining energy, another may have to wait. Entanglement can refund part of spending and share that refund with nearby allies.")),new FieldGuide.Section("Details 5",List.of("Secondary breaks and remote collection cannot recursively farm resonance. Read individual modifier entries for stage values and exact conditions.")))),
        new FieldGuide.Entry("influences",FieldGuide.Category.STATIONS,FieldGuide.Group.ALL,"The Influencer","examplemod:influencer",List.of("Components start without an influence. The Influencer assigns Nether or End influence once and rerolls eligible modifiers with a stronger matching theme.","Matching themed modifier families have sixfold relative weight. Other-influence families are excluded. Neutral families remain available, and influence-exclusive families require their matching influence.","An influence is permanent. You cannot remove it, switch it or keep applying the same influence to fish for better rolls. Annulment does not reset that rule.","Nether names have an ember-colored pulse; End names have a violet shimmer. Inventory icons keep their original appearance. A piece's individual influence is retained when assembled.","Influence changes roll eligibility and weighting, not the meaning of its original excavation score. This prototype has no crafting recipe and is available in creative mode."),List.of("modifier_basics","unveiler","locker"),"nether end influence influencer permanent themed smelting phasebound teleport",List.of(new FieldGuide.Section("Assign an influence",List.of("Components start without an influence. The Influencer assigns Nether or End influence once and rerolls eligible modifiers with a stronger matching theme.")),new FieldGuide.Section("Roll weighting",List.of("Matching themed modifier families have sixfold relative weight. Other-influence families are excluded. Neutral families remain available, and influence-exclusive families require their matching influence.")),new FieldGuide.Section("Permanent choice",List.of("An influence is permanent. You cannot remove it, switch it or keep applying the same influence to fish for better rolls. Annulment does not reset that rule.")),new FieldGuide.Section("Appearance",List.of("Nether names have an ember-colored pulse; End names have a violet shimmer. Inventory icons keep their original appearance. A piece's individual influence is retained when assembled.")),new FieldGuide.Section("Prototype access",List.of("Influence changes roll eligibility and weighting, not the meaning of its original excavation score. This prototype has no crafting recipe and is available in creative mode.")))),
        new FieldGuide.Entry("unveiler",FieldGuide.Category.STATIONS,FieldGuide.Group.ALL,"The Unveiler and ancient runes","examplemod:unveiler",List.of("Epic and higher components may carry a hidden ancient modifier written as unreadable runes. It replaces a modifier slot rather than adding unlimited extra rolls.","The Unveiler shows three fixed legal choices. Each choice includes a modifier, scaling grade and base value. Select one to reveal it on the component.","The choices are saved, not freshly rerolled every time the menu opens. Revealing consumes the hidden slot. Role pools, rarity, exclusivity, influence and existing modifiers still constrain the choices.","The Unveiler acts on recovered pieces, not assembled tools. Corrupted components cannot be modified. The prototype has no crafting recipe."),List.of("modifier_basics","influences","corruption"),"ancient runes hidden unveil three choices reveal",List.of(new FieldGuide.Section("Overview",List.of("Epic and higher components may carry a hidden ancient modifier written as unreadable runes. It replaces a modifier slot rather than adding unlimited extra rolls.")),new FieldGuide.Section("Details 2",List.of("The Unveiler shows three fixed legal choices. Each choice includes a modifier, scaling grade and base value. Select one to reveal it on the component.")),new FieldGuide.Section("Details 3",List.of("The choices are saved, not freshly rerolled every time the menu opens. Revealing consumes the hidden slot. Role pools, rarity, exclusivity, influence and existing modifiers still constrain the choices.")),new FieldGuide.Section("Details 4",List.of("The Unveiler acts on recovered pieces, not assembled tools. Corrupted components cannot be modified. The prototype has no crafting recipe.")))),
        new FieldGuide.Entry("anuller",FieldGuide.Category.STATIONS,FieldGuide.Group.ALL,"The Anuller","examplemod:anuller",List.of("The Anuller randomly removes one unlocked modifier from a recovered component. It cannot target a permanently locked modifier.","It does not remove influence or make influence assignment repeatable. A corrupted component is terminal and cannot be annulled.","This prototype works on pieces, not assembled tools, and has no crafting recipe."),List.of("locker","influences","corruption"),"anuller annuller annul annulment remove modifier",List.of(new FieldGuide.Section("Overview",List.of("The Anuller randomly removes one unlocked modifier from a recovered component. It cannot target a permanently locked modifier.")),new FieldGuide.Section("Details 2",List.of("It does not remove influence or make influence assignment repeatable. A corrupted component is terminal and cannot be annulled.")),new FieldGuide.Section("Details 3",List.of("This prototype works on pieces, not assembled tools, and has no crafting recipe.")))),
        new FieldGuide.Entry("locker",FieldGuide.Category.STATIONS,FieldGuide.Group.ALL,"The Locker","examplemod:modifier_locker",List.of("The Locker permanently protects one revealed modifier on a component. It cannot be removed by the Anuller or targeted by modification operations that respect the lock.","You may lock only one modifier. You cannot move that lock to a different modifier later. Hidden ancient runes must be unveiled before locking a revealed choice.","Influence assignment preserves a compatible lock and rejects a conflicting assignment. Corruption never selects the locked modifier as a target.","The prototype has no crafting recipe and works on recovered pieces."),List.of("anuller","unveiler","influences","corruption"),"lock locked permanent protect",List.of(new FieldGuide.Section("Overview",List.of("The Locker permanently protects one revealed modifier on a component. It cannot be removed by the Anuller or targeted by modification operations that respect the lock.")),new FieldGuide.Section("Details 2",List.of("You may lock only one modifier. You cannot move that lock to a different modifier later. Hidden ancient runes must be unveiled before locking a revealed choice.")),new FieldGuide.Section("Details 3",List.of("Influence assignment preserves a compatible lock and rejects a conflicting assignment. Corruption never selects the locked modifier as a target.")),new FieldGuide.Section("Details 4",List.of("The prototype has no crafting recipe and works on recovered pieces.")))),
        new FieldGuide.Entry("scaling_randomizer",FieldGuide.Category.STATIONS,FieldGuide.Group.ALL,"The Scaling Randomizer","examplemod:scaling_randomizer",List.of("The Scaling Randomizer rerolls scaling grades on the component's unlocked modifiers. It does not reroll the base values, value-tier provenance or excavation score.","A locked modifier retains its grade. Corrupted pieces cannot be randomized. Influence remains permanent and unchanged.","The prototype has no crafting recipe and works on recovered pieces."),List.of("scaling_and_quality","locker","corruption"),"randomizer scaling grade reroll F D C B A S",List.of(new FieldGuide.Section("Overview",List.of("The Scaling Randomizer rerolls scaling grades on the component's unlocked modifiers. It does not reroll the base values, value-tier provenance or excavation score.")),new FieldGuide.Section("Details 2",List.of("A locked modifier retains its grade. Corrupted pieces cannot be randomized. Influence remains permanent and unchanged.")),new FieldGuide.Section("Details 3",List.of("The prototype has no crafting recipe and works on recovered pieces.")))),
        new FieldGuide.Entry("restoration",FieldGuide.Category.STATIONS,FieldGuide.Group.ALL,"The Restorer","examplemod:component_restorer",List.of("The Restorer improves a recovered component's current quality in ten-point steps, up to 120%. Quality above 100% strengthens contributions that have room below their caps.","The original excavation score remains recorded. Restoration does not reroll its modifier families, values, tiers, grades or influence.","Corruption prevents further restoration. Restore a piece before taking that final gamble. This prototype has no crafting recipe."),List.of("scaling_and_quality","corruption"),"restorer restore restoration quality extraction 120 percent",List.of(new FieldGuide.Section("Overview",List.of("The Restorer improves a recovered component's current quality in ten-point steps, up to 120%. Quality above 100% strengthens contributions that have room below their caps.")),new FieldGuide.Section("Details 2",List.of("The original excavation score remains recorded. Restoration does not reroll its modifier families, values, tiers, grades or influence.")),new FieldGuide.Section("Details 3",List.of("Corruption prevents further restoration. Restore a piece before taking that final gamble. This prototype has no crafting recipe.")))),
        new FieldGuide.Entry("corruption",FieldGuide.Category.STATIONS,FieldGuide.Group.ALL,"The Corruptor","examplemod:corruptor",List.of("Corruption is a final gamble on a recovered component. Once corrupted, no more component modifications are allowed.","Possible outcomes include strengthening or weakening an unlocked modifier, raising or lowering a scaling grade, adding or removing an eligible unlocked modifier, restoring or damaging quality, or leaving the piece otherwise unchanged.","Only eligible outcomes are rolled. Locked modifiers cannot be selected. Quality limits, modifier limits, role pools and permanent influence rules still apply.","Plan your restoration, revelation, influence and lock before corrupting. The prototype has no crafting recipe. Further sculk-related progression is planned."),List.of("restoration","unveiler","influences","locker"),"corrupt corruption sculk final gamble good bad outcomes",List.of(new FieldGuide.Section("Overview",List.of("Corruption is a final gamble on a recovered component. Once corrupted, no more component modifications are allowed.")),new FieldGuide.Section("Details 2",List.of("Possible outcomes include strengthening or weakening an unlocked modifier, raising or lowering a scaling grade, adding or removing an eligible unlocked modifier, restoring or damaging quality, or leaving the piece otherwise unchanged.")),new FieldGuide.Section("Details 3",List.of("Only eligible outcomes are rolled. Locked modifiers cannot be selected. Quality limits, modifier limits, role pools and permanent influence rules still apply.")),new FieldGuide.Section("Details 4",List.of("Plan your restoration, revelation, influence and lock before corrupting. The prototype has no crafting recipe. Further sculk-related progression is planned."))))
    );}
